addedCss:
// INTERFACE-AGU-003 — apresentação, sem mudança em corpus ou persistência.
const readerPlumCss=`
#agu-reader{--reader-accent:#633c69;--reader-ink:#29262d;--reader-muted:#5d535e;--reader-line:#e0d9df;--reader-wash:#f1e8f3;color:var(--reader-ink)}
#agu-reader .agu-pane{border-color:var(--reader-line);border-radius:14px}
#agu-reader .agu-muted,#agu-reader .agu-reader-location{color:var(--reader-muted)}
#agu-reader .agu-primary,#agu-reader .agu-tabs button[aria-pressed=true],#agu-reader .agu-matter-option[aria-pressed=true],#agu-reader .agu-mobile button[aria-pressed=true]{background:var(--reader-accent);border-color:var(--reader-accent);color:white}
#agu-reader a{color:var(--reader-accent);text-decoration:underline;text-underline-offset:2px}
#agu-reader .agu-matter-badge{background:var(--reader-wash);border-color:#c9b5cf;color:#543358}
#agu-reader .agu-index-entry.selected,#agu-reader .agu-unit.selected{background:var(--reader-wash);border-color:var(--reader-accent)}
#agu-reader .agu-unit{border-left-color:#d7cdd9}
#agu-reader .agu-notice,#agu-reader .agu-paper-context{background:#f5f2ef}
#agu-reader .agu-notice{border-left-color:#a58da8}
#agu-reader .agu-light,#agu-reader .agu-tabs button:not([aria-pressed=true]),#agu-reader .agu-mobile button:not([aria-pressed=true]){background:#fff;color:var(--reader-ink);border-color:#c9beca}
#agu-reader :focus-visible{outline:3px solid #87531e;outline-offset:3px}
#agu-reader .agu-document .agu-unit p{color:var(--reader-ink);line-height:1.75}
#agu-reader .agu-document .agu-unit.selected{border-left-color:var(--reader-accent)}
#agu-reader .agu-document .agu-step-prev,#agu-reader .agu-document .agu-step-next{min-height:44px;white-space:normal}
@media(max-width:1100px){
 #agu-reader .top{margin-bottom:12px}
 #agu-reader .agu-mobile{background:#f8f6f2;border-color:var(--reader-line);margin:8px 0 12px}
 #agu-reader .agu-mobile button{flex:1 1 0;min-width:44px;min-height:48px}
 #agu-reader .agu-pane{width:100%;padding:clamp(12px,3vw,24px);max-width:100%;overflow-wrap:anywhere}
 #agu-reader .agu-document h2{font-size:1.75rem;margin:12px 0}
 #agu-reader .agu-document .agu-unit{font-size:1.125em;padding:16px 12px}
 #agu-reader .agu-document .agu-unit p{line-height:1.8}
 #agu-reader .agu-muted{font-size:.875em}
 #agu-reader .agu-tabs{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,8rem),1fr));gap:8px}
 #agu-reader .agu-tabs button{min-height:48px}
 #agu-reader .agu-paper-context{padding:10px}
 #agu-reader .agu-paper-context button{max-width:100%;white-space:normal}
 #agu-reader .agu-document .agu-step-prev,#agu-reader .agu-document .agu-step-next{margin:3px 4px 3px 0;max-width:100%}
 #agu-reader .agu-index,#agu-reader .agu-related{overflow:visible}
}
`;
